import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`listing-sync-audit`,heroTitle:`Fix every listing discrepancy in minutes`,heroSubtitle:`Perplexity Computer analyzes your site, audits your listings across Google, Yelp, and top directories, and writes corrected copy — automatically.`,inputUrlCta:`Audit my listings`,inputUrlPlaceholder:`yourbusiness.com`,inputUrlPrefill:`Go to {url} and extract the business name, address, phone number, hours of operation, services offered, photos, and business description. Then check this information for consistency across Google Business Profile, Yelp, Facebook, Apple Maps, Bing Places, and the top 10 industry-relevant directories. For each platform: 1) Record the exact NAP (name, address, phone), hours, categories, description, and photo count currently listed. 2) Flag every discrepancy — misspelled names, outdated hours, wrong phone numbers, missing services, inconsistent descriptions, low-quality or missing photos. 3) Score each listing on a 0-100 consistency scale. 4) Write corrected, platform-optimized copy for every listing that has errors — matching character limits and formatting rules for each directory. 5) Produce a master audit report with a summary dashboard, a platform-by-platform discrepancy table, corrected copy ready to paste, and a prioritized action plan ranked by local SEO impact. When I approve the changes, push the corrected information live to each platform.`,heroOverlaySteps:[`Analyzing your website for NAP, hours, services, and photos`,`Checking your listings across Google, Yelp, Facebook, Apple Maps, and key directories`,`Flagging every discrepancy and writing corrected copy per platform`,`Audit report with corrected listings and action plan — ready to push live`],generatingSteps:[`Visiting {url} to extract your business name, address, phone, hours, and services`,`Designing an agent to audit your listings across Google, Yelp, Facebook, Apple Maps, and top directories`,`Configuring discrepancy detection and platform-specific copy correction`,`Setting up your listing sync dashboard with scoring and one-click publishing`],featureSectionTitle:`From URL to synced listings everywhere`,featureCardTitles:[`Connects to your local SEO stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Search Console, Google Sheets, Google Drive, Notion, Slack — Computer pipes your audit reports and corrected listings into the tools you already use.`,`Consistency scorecards per platform. Discrepancy tables with exact diffs. Corrected copy formatted for each directory. A prioritized action plan ranked by local SEO impact.`],capabilitySectionTitle:`Your listing manager, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to perfectly synced listings.`,capabilityCards:[{title:`Listing Audit`,description:`Computer can analyze Google Business Profile, Yelp, Facebook, Apple Maps, and dozens of directories — and flag every NAP, hours, and description mismatch.`},{title:`Discrepancy Scoring`,description:`Computer can score each listing on a 0-100 consistency scale — so you see exactly which platforms hurt your local rankings the most.`},{title:`Corrected Copy`,description:`Computer can write platform-optimized descriptions, hours, and service lists for every directory — formatted to each site's character limits and rules.`},{title:`Connect Your Tools`,description:`Computer can sync with Google Sheets, Google Drive, Notion, and Slack — so audit reports and corrected listings flow into your existing workflow.`},{title:`Remember & Learn`,description:`Computer can remember your verified business data, past audits, and correction history — so every future sync starts from your source of truth.`},{title:`Monitor & Alert`,description:`Computer can re-audit your listings weekly and alert you the moment a directory reverts your data or a new discrepancy appears.`}]});export{t as default};
